import{_ as o,o as d,c as a,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"开发总览","description":"","frontmatter":{},"headers":[],"relativePath":"dev/start.md","filePath":"dev/start.md","lastUpdated":null}'),s={name:"dev/start.md"};function r(l,t,n,i,c,h){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="开发总览" tabindex="-1">开发总览 <a class="header-anchor" href="#开发总览" aria-label="Permalink to &quot;开发总览&quot;">​</a></h1><p>这一章是给<strong>想自己写 Mod、或者想改框架本身</strong>的人看的。如果你只是想玩游戏、用别人做的 Mod，看完前面的「安装部署 / 功能接入 / 使用指南」就够了。</p><h2 id="两条路-写-mod-还是改框架" tabindex="-1">两条路：写 Mod，还是改框架 <a class="header-anchor" href="#两条路-写-mod-还是改框架" aria-label="Permalink to &quot;两条路：写 Mod，还是改框架&quot;">​</a></h2><p>请先分清你要做哪件事，因为难度差别很大：</p><table tabindex="0"><thead><tr><th></th><th>写一个 Mod</th><th>改框架本身</th></tr></thead><tbody><tr><td>你要做什么</td><td>新建文件夹 + 写一个 <code>mod.json</code></td><td>改 C# 源码 → 重编译 DLL → 重打包 APK</td></tr><tr><td>需要工具</td><td><strong>记事本就够了</strong></td><td>Visual Studio / Mono + Python + 签名工具</td></tr><tr><td>需要懂编程吗</td><td><strong>完全不需要</strong></td><td>需要（C# 3.0）</td></tr><tr><td>影响范围</td><td>只影响你自己的游戏</td><td>影响整个框架、所有玩家</td></tr><tr><td>从哪开始</td><td><a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a></td><td><a href="/AtlanticFleetSite/docs/dev/codebase">框架源码结构</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">绝大多数人只需要左边那一列</p><p>框架的设计目标就是「<strong>不写一行代码</strong>也能做出舰船、编队、改数值、换模型」。真正要动 C# 的场景很少。</p></div><h2 id="这一章包含什么" tabindex="-1">这一章包含什么 <a class="header-anchor" href="#这一章包含什么" aria-label="Permalink to &quot;这一章包含什么&quot;">​</a></h2><ul><li><strong><a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a></strong> —— 一个 Mod 文件里所有字段的权威字典</li><li><strong><a href="/AtlanticFleetSite/docs/dev/param-keys">参数键全表</a></strong> —— 23 个可调参数的键名 / 默认值 / 边界 / 含义</li><li><strong><a href="/AtlanticFleetSite/docs/dev/ship-fleet-schema">舰船与编队定义</a></strong> —— <code>ships[]</code> 和 <code>fleets[]</code> 的每个字段</li><li><strong><a href="/AtlanticFleetSite/docs/dev/assetbundle">制作 AssetBundle 模型</a></strong> —— 用 Unity 导出能用的模型包</li><li><strong><a href="/AtlanticFleetSite/docs/dev/publish">发布你的 Mod 到仓库</a></strong> —— 让别人一键装上你的作品</li><li><strong><a href="/AtlanticFleetSite/docs/dev/codebase">框架源码结构</a></strong> —— 100 个源文件都是干嘛的</li><li><strong><a href="/AtlanticFleetSite/docs/dev/build-env">编译环境搭建</a></strong> —— 从零把编译链跑起来</li><li><strong><a href="/AtlanticFleetSite/docs/dev/cs30-limits">C# 3.0 兼容约束</a></strong> —— 写代码前必读的「不能用什么」</li><li><strong><a href="/AtlanticFleetSite/docs/dev/hack">如何修改框架本身</a></strong> —— 挂钩点在哪、怎么加新功能</li><li><strong><a href="/AtlanticFleetSite/docs/dev/logging-api">调试与日志接口</a></strong> —— <code>ModLog</code> / 探针 / 落盘机制</li><li><strong><a href="/AtlanticFleetSite/docs/dev/contributing">贡献与规范</a></strong> —— 怎么把改动合回来</li></ul><h2 id="一个最重要的前提" tabindex="-1">一个最重要的前提 <a class="header-anchor" href="#一个最重要的前提" aria-label="Permalink to &quot;一个最重要的前提&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">改完必须重开游戏</p><p>框架在<strong>游戏启动时</strong>扫描一次 Mod 目录、读一次参数。运行中改文件不会生效。所有「改了没反应」的问题，第一步都是<strong>完全退出游戏再重开</strong>。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>先看个最小例子 → <a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a></li><li>想直接抄一个 → <a href="/AtlanticFleetSite/docs/quickstart">快速开始</a></li><li>要改框架 → <a href="/AtlanticFleetSite/docs/dev/build-env">编译环境搭建</a></li></ul>',12)])])}const f=o(s,[["render",r]]);export{u as __pageData,f as default};
